<?php namespace App\Http\Requests; use Illuminate\Foundation\Http\FormRequest; class CareContentRequest extends FormRequest { public function authorize(): bool{return in_array($this->user()?->role,['admin','vet','shelter'],true);} public function rules(): array{return ['title'=>'required|string|max:255','category'=>'required|string|max:100','type'=>'required|in:article,video,faq','content'=>'required|string','media_url'=>'nullable|url','is_published'=>'boolean'];} }